// Package migrations embeds Tether's one goose migration set (port plan section 3). The set is
// SQLite only (the app's SQL is SQLite's), so the tree holds sqlite/ and no postgres/ directory.
// 00001_schema.sql is the squashed schema of the old store at its migration 0101, generated by
// internal/migrate's schema test from the old migrations and proven equal to them there. No
// per-version ladders from the old tree belong here.
package migrations

import (
	"embed"
	"io/fs"
)

//go:embed sqlite/*.sql
var fsys embed.FS

// FS returns the migration tree and its root directory, in the layout the database module expects
// (<root>/sqlite/NNNNN_name.sql).
func FS() (fs.FS, string) { return fsys, "." }
